import pathlib,json,html
out=pathlib.Path('.archify/diccionario-db-test-20261104'); data=json.loads((out/'data.json').read_text(encoding='utf-8'))
payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
page=r'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Archivo de datos // db_test</title><style>
:root{color-scheme:dark;--bg:#0a0a0c;--panel:#141619;--red:#ff3832;--soft:#b8c4ca;--white:#f0f4f8;--amber:#f4c270;--green:#8de1ad}*{box-sizing:border-box}body{margin:0;background:linear-gradient(#ffffff05 1px,transparent 1px),linear-gradient(90deg,#ffffff05 1px,transparent 1px),var(--bg);background-size:32px 32px;color:var(--white);font:15px/1.6 Consolas,Monaco,monospace}body:after{content:"";position:fixed;inset:0;pointer-events:none;background:repeating-linear-gradient(transparent 0 3px,#0002 4px);z-index:3}.wrap{max-width:1500px;margin:auto;padding:28px}header{border-left:5px solid #b80f0a;padding:14px 22px;background:#141619ed}.stamp{font-size:.75rem;letter-spacing:.15em;color:var(--red);font-weight:bold}h1{font-size:clamp(1.7rem,4vw,3.4rem);line-height:1.1;margin:.4em 0}h2{color:var(--white);font-size:1.2rem;margin:2em 0 .7em;border-bottom:1px solid #9d1c1c;padding-bottom:8px}h3{margin:.5em 0;color:var(--green)}p{max-width:110ch}.dim{color:var(--soft)}.notice{border:1px solid #765c31;background:#272016;padding:14px;color:#ffe0a5}.metrics{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.metric{background:#141619;border:1px solid #414449;padding:10px 18px;color:var(--green)}.controls{display:flex;gap:12px;flex-wrap:wrap;position:sticky;top:0;z-index:2;background:#0a0a0cf7;padding:14px 0}input,select,button{font:inherit;color:var(--white);background:#1c2024;border:1px solid #666;padding:10px}input{min-width:240px;flex:1}button{cursor:pointer}button:hover,button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--red)}details{background:var(--panel);border:1px solid #3e4448;border-left:3px solid #b80f0a;margin:10px 0}summary{padding:13px;cursor:pointer;font-weight:bold;overflow-wrap:anywhere}summary:hover{background:#242629}.body{padding:0 14px 16px}.field{border-top:1px solid #353a40;padding:12px 0}.field h4{margin:0 0 6px;color:var(--white);font-size:1rem;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:6px 18px}.label{color:#a6b5be;font-size:.8rem;text-transform:uppercase;display:block}.value{overflow-wrap:anywhere}.tag{font-size:.72rem;padding:3px 6px;background:#39201e;color:#ffaaa3;margin-left:8px}.tag.view{background:#1b3129;color:#a3efbf}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0d1012;padding:12px;border:1px solid #353a40;font-size:.83rem}.toolbar-note{color:var(--amber)}a{color:#9ee2bf}footer{border-top:1px solid #6e2926;margin-top:30px;padding:20px 0;color:var(--soft)}.empty{padding:16px;color:var(--amber)}@media(max-width:600px){.wrap{padding:14px}.controls{position:static}input{min-width:100%}}
</style></head><body><main class="wrap"><header><div class="stamp">CONFIDENTIAL // UMBRELLA CORP. DATA ARCHIVE &nbsp; // &nbsp; BIOHAZARD LEVEL 4</div><h1>Diccionario de datos<br><span style="color:#ff4943">db_test</span></h1><p>Expediente de estructura · comercio electrónico · lectura humana del respaldo</p><div class="dim">FUENTE: respaldo10_28.1.sql · SHA-256: <span id="hash"></span></div></header>
<div class="metrics" id="metrics"></div><p class="notice"><strong>Alcance:</strong> fotografía del respaldo; no se consultó el servidor ni se leyeron registros para describir personas. Las definiciones SQL y nombres están comprobados en el archivo. Las explicaciones basadas en nombres y las clasificaciones semánticas son interpretaciones; confirme su significado con quien diseñó la base.</p>
<h2>01 // Cómo leer este archivo</h2><p><strong>Admite NULL</strong> indica si puede guardarse explícitamente la ausencia de un valor. <strong>Puede omitirse</strong> indica si es posible dejar el campo fuera del INSERT: un campo obligatorio puede omitirse cuando tiene valor predeterminado o se genera solo. La respuesta presupone modo estricto y ausencia de triggers que alteren el valor; el comportamiento de sesión puede variar.</p><p>Las columnas de vistas se marcan como <strong>proyectadas</strong>. El respaldo incluye alias y expresiones de sus vistas, pero las estructuras temporales con <code>1 AS ...</code> no prueban su tipo ni su nulabilidad real: deben consultarse en MySQL. Las claves compuestas y reglas de varias columnas se muestran completas en cada tabla.</p>
<h2>02 // Buscar expedientes</h2><div class="controls"><label class="sr" for="query">Buscar</label><input id="query" placeholder="Tabla, campo, tipo, clave o texto…" autocomplete="off"><label for="kind">Clase</label><select id="kind"><option value="">Todas</option><option>Tabla</option><option>Vista</option><option>Trigger</option><option>Procedimiento</option></select><label for="origin">Origen</label><select id="origin"><option value="">Todos</option><option>Almacenado</option><option>Derivado</option><option>Derivado y almacenado</option><option>Proyectado</option></select><button id="clear" type="button">Limpiar</button></div><p class="toolbar-note" id="count" aria-live="polite"></p><div id="records"></div>
<h2>03 // Glosario y ejemplos</h2><details><summary>Conceptos fundamentales</summary><div class="body"><p><strong>Tabla:</strong> conjunto de filas del mismo tipo. <strong>Campo o columna:</strong> dato que describe cada fila. <strong>Vista:</strong> consulta guardada que presenta columnas de otras fuentes. <strong>Clave primaria:</strong> identifica una fila; <strong>única:</strong> evita repeticiones según las reglas de MySQL; una clave única puede admitir varios NULL.</p><p><strong>Clave foránea:</strong> regla que vincula columnas con una fila referenciada; algunas usan varias columnas juntas. <strong>Índice:</strong> estructura para acelerar búsquedas o imponer unicidad. <strong>CHECK:</strong> condición que deben cumplir los valores. <strong>Trigger:</strong> acción que se ejecuta por un evento en una tabla. <strong>Procedimiento:</strong> conjunto de instrucciones que se invoca por nombre.</p><p><strong>Monovalorado:</strong> un valor SQL por celda; JSON puede contener varias piezas. <strong>Simple/compuesto:</strong> si representa una sola pieza o una estructura. <strong>Naturaleza:</strong> cualitativa, cuantitativa, temporal o estructurada. <strong>Escala:</strong> nominal identifica categorías; intervalo mide diferencias; razón además tiene cero significativo. Estas clasificaciones dependen del uso, no solo del tipo SQL.</p><p><strong>Dominio:</strong> valores permitidos por tipo y reglas; el significado de negocio puede imponer condiciones adicionales no declaradas. <strong>Almacenado:</strong> persiste en la tabla; <strong>derivado:</strong> se calcula; <strong>derivado y almacenado:</strong> MySQL calcula y guarda el resultado; <strong>proyectado:</strong> se presenta en una vista.</p></div></details><details><summary>Ejemplos sin datos reales</summary><div class="body"><p>En <code>tb_buyer_orders</code>, <code>creation_date</code> no admite NULL y puede omitirse porque se genera con <code>CURRENT_TIMESTAMP</code>. <code>cart_ID</code> admite NULL y puede omitirse: su predeterminado es NULL. <code>order_number</code> no admite NULL y no declara valor predeterminado; en modo estricto debe proporcionarse.</p><p><code>grand_total</code> se calcula a partir de subtotal, descuentos, impuestos y envío, y se almacena. <code>tbd_products_categories</code> relaciona productos y categorías; una clave única evita repetir el mismo par. <code>tbc_categories.sup_id_category</code> sugiere una categoría superior por su nombre, pero el respaldo no declara una clave foránea para ese campo.</p><p>Las consultas siguientes son ejemplos de estructura, sin obtener datos personales:</p><pre>SHOW CREATE TABLE db_test.tb_buyer_orders;\nSHOW CREATE VIEW db_test.vw_trazabilidad_productos;</pre><p>La consulta del respaldo no demuestra permisos del servidor ni que las definiciones sigan vigentes.</p></div></details><footer>ARCHIVO DE REFERENCIA // Definiciones extraídas sin filas. Anexo SQL de lectura: <a href="anexo_definiciones.sql">anexo_definiciones.sql</a> · <a href="campos_clasificados.csv">CSV de campos</a> · <a href="mapa_archify.html">mapa Archify</a></footer></main>
<script>const DATA=__PAYLOAD__;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const f=DATA.fields;$('#hash').textContent=DATA.sha256;$('#metrics').innerHTML=[[DATA.tables.length,'TABLAS'],[DATA.views.length,'VISTAS'],[DATA.triggers.length,'TRIGGERS'],[DATA.routines.length,'PROCEDIMIENTOS'],[f.length,'CAMPOS']].map(x=>`<div class="metric"><strong>${x[0]}</strong> ${x[1]}</div>`).join('');
const display={tipo_sql:'Tipo SQL',definicion_sql:'Definición comprobada',admite_null:'Admite NULL',puede_omitirse:'Puede omitirse al insertar',predeterminado:'Predeterminado',cantidad:'Cantidad de valores',composicion:'Composición',naturaleza:'Naturaleza',escala:'Escala',dominio:'Dominio',origen:'Origen',claves_restricciones:'Claves y restricciones',explicacion:'Explicación',evidencia:'Evidencia'};
function fieldCard(x){return `<article class="field"><h4>${esc(x.campo)}</h4><div class="grid">${Object.entries(display).map(([k,v])=>`<div><span class="label">${esc(v)}</span><span class="value">${esc(x[k])}</span></div>`).join('')}</div></article>`}
function render(){const q=$('#query').value.trim().toLocaleLowerCase('es'),kind=$('#kind').value,origin=$('#origin').value;let results=[];for(const t of DATA.tables){let items=f.filter(x=>x.objeto===t.name);let whole=(t.name+' '+t.constraints.join(' ')).toLowerCase().includes(q);items=items.filter(x=>(!origin||x.origen===origin)&&(whole||JSON.stringify(x).toLowerCase().includes(q)));if((!kind||kind==='Tabla')&&items.length){results.push(`<details><summary>${esc(t.name)} <span class="tag">TABLA · ${items.length} CAMPOS</span></summary><div class="body"><p class="dim">Comprobado en el respaldo, línea ${t.line}. Las reglas siguientes incluyen claves, índices y restricciones.</p><pre>${esc(t.constraints.join('\n'))}</pre>${items.map(fieldCard).join('')}</div></details>`);}}
for(const v of DATA.views){let items=f.filter(x=>x.objeto===v.name);let whole=(v.name+' '+v.body).toLowerCase().includes(q);items=items.filter(x=>(!origin||x.origen===origin)&&(whole||JSON.stringify(x).toLowerCase().includes(q)));if((!kind||kind==='Vista')&&items.length)results.push(`<details><summary>${esc(v.name)} <span class="tag view">VISTA · ${items.length} CAMPOS</span></summary><div class="body"><p class="dim">Consulta definida en el respaldo, línea ${v.line}; tipos finales no comprobados.</p><pre>${esc(v.body)}</pre>${items.map(fieldCard).join('')}</div></details>`)}
for(const [list,label] of [[DATA.triggers,'Trigger'],[DATA.routines,'Procedimiento']]){if(origin||kind&&kind!==label)continue;for(const a of list)if((a.name+' '+a.sql).toLowerCase().includes(q))results.push(`<details><summary>${esc(a.name)} <span class="tag">${label.toUpperCase()}</span></summary><div class="body"><p>Línea ${a.line}. Definición SQL; la cuenta DEFINER se omitió.</p><pre>${esc(a.sql)}</pre></div></details>`)}$('#records').innerHTML=results.join('')||'<p class="empty">Sin coincidencias. Ajuste el filtro o el texto.</p>';$('#count').textContent=`${results.length} expedientes coinciden`;}
for(const e of ['query','kind','origin'])$('#'+e).addEventListener('input',render);$('#clear').addEventListener('click',()=>{$('#query').value='';$('#kind').value='';$('#origin').value='';render();$('#query').focus()});render();</script></body></html>'''
(out/'diccionario_interactivo.html').write_text(page.replace('__PAYLOAD__',payload),encoding='utf-8')
